import numpy as np
def equation(t, x, v, params):
    w=np.pi/10
    return (params[0] + params[1]*v + params[2]*v**2 + params[3]/x + params[4]*np.sqrt(v)*np.log(x)
            + params[5]*np.tanh(x) + params[6]*x*np.sqrt(v) + params[7]*np.log(v)
            + params[8]*np.cos(w*t) + params[9]*np.sin(w*t))
